@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/geist";
@import "@fontsource-variable/geist-mono";

/* Light (faithful): white page, #19282f slate ink and pill buttons, #828385 grey secondary
   text, #e9ebef media frames, #f6f8fb cards behind pale hairlines, and two faint lights
   (aqua #0094d8, lime #a1d62c) washing the hero card and the closing band. */
:root {
  --background: #ffffff;
  --foreground: #19282f;
  --card: #f9fafc;
  --card-foreground: #19282f;
  --popover: #ffffff;
  --popover-foreground: #19282f;
  --primary: #19282f;
  --primary-foreground: #ffffff;
  --secondary: #f6f8fb;
  --secondary-foreground: #19282f;
  --muted: #e9ebef;
  --muted-foreground: #828385;
  --accent: #f1f3f6;
  --accent-foreground: #43494e;
  --destructive: #c8372d;
  --destructive-foreground: #ffffff;
  --border: #e4e7eb;
  --input: #d5dae0;
  --ring: #43494e;
  --highlight: #a1d62c;
  --highlight-foreground: #19282f;
  --glow: #0094d8;
  --chart-1: #6f9a1b;
  --chart-2: #13915a;
  --chart-3: #d9b40f;
  --chart-4: #19282f;
  --chart-5: #0094d8;
  --sidebar: #f6f8fb;
  --sidebar-foreground: #19282f;
  --sidebar-primary: #19282f;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e9ebef;
  --sidebar-accent-foreground: #19282f;
  --sidebar-border: #e4e7eb;
  --sidebar-ring: #43494e;

  --typeface-body: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 77.5rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark sibling: deep slate page and cards, pale ink, pale pill buttons, the same aqua and
   lime lights a touch stronger so the washes still read. */
.dark {
  --background: #0e171b;
  --foreground: #eef2f4;
  --card: #142128;
  --card-foreground: #eef2f4;
  --popover: #142128;
  --popover-foreground: #eef2f4;
  --primary: #eef2f4;
  --primary-foreground: #0e171b;
  --secondary: #172630;
  --secondary-foreground: #eef2f4;
  --muted: #1c2b33;
  --muted-foreground: #8d979d;
  --accent: #1f3039;
  --accent-foreground: #c9d1d6;
  --destructive: #ef6b5f;
  --destructive-foreground: #0e171b;
  --border: #23343d;
  --input: #2d414b;
  --ring: #b6c1c7;
  --highlight: #b6e64a;
  --highlight-foreground: #0e171b;
  --glow: #2bb3f0;
  --chart-1: #b6e64a;
  --chart-2: #2fc483;
  --chart-3: #f0cd2e;
  --chart-4: #eef2f4;
  --chart-5: #2bb3f0;
  --sidebar: #142128;
  --sidebar-foreground: #eef2f4;
  --sidebar-primary: #eef2f4;
  --sidebar-primary-foreground: #0e171b;
  --sidebar-accent: #1f3039;
  --sidebar-accent-foreground: #eef2f4;
  --sidebar-border: #23343d;
  --sidebar-ring: #b6c1c7;
}
